288	/**
289	 * Cursors are opaque to callers: base64url of `<sortValue>|<id>`. Encoding the
290	 * sort value alongside the id is what lets `listX` resume from a stable point
291	 * even when two rows share a timestamp.
292	 */
293	export function encodeCursor(id: string, sortValue: string): string {
294	  return Buffer.from(`${sortValue}${CURSOR_SEPARATOR}${id}`, "utf8").toString(
295	    "base64url",
296	  );
