299	export function decodeCursor(
300	  cursor: string,
301	): { id: string; sortValue: string } | null {
302	  let decoded: string;
303	  try {
304	    decoded = Buffer.from(cursor, "base64url").toString("utf8");
305	  } catch {
306	    return null;
307	  }
308	
309	  const separatorAt = decoded.lastIndexOf(CURSOR_SEPARATOR);
310	  if (separatorAt <= 0 || separatorAt === decoded.length - 1) return null;
311	
312	  return {
313	    sortValue: decoded.slice(0, separatorAt),
314	    id: decoded.slice(separatorAt + 1),
315	  };
