763	  userId: UserId,
764	): Promise<{ token: string; expiresAt: IsoTimestamp }> {
765	  const token = randomToken(TOKEN_BYTES);
766	  const expiresAt = toIsoTimestamp(
767	    new Date(Date.now() + SESSION_TTL_DAYS * MS_PER_DAY),
768	  );
769	
770	  await sessionRepo.createSession(userId, hashToken(token), expiresAt);
771	
772	  return { token, expiresAt };
