790	export async function resolveActorForOrg(
791	  principal: SessionPrincipal,
792	  orgSlug: string,
793	): Promise<Actor | null> {
794	  const org = await orgRepo.findOrgBySlug(orgSlug);
795	  if (!org) return null;
796	
797	  const member = await memberRepo.findMember(org.id, principal.userId);
798	  if (!member || member.status !== "active") return null;
799	
800	  const actor: Actor = {
801	    userId: principal.userId,
802	    orgId: org.id,
803	    role: member.role,
804	  };
805	
806	  assertOrgScope(actor, org.id);
807	
808	  await memberRepo.touchLastSeen(
809	    org.id,
810	    principal.userId,
811	    toIsoTimestamp(new Date()),
