913	/** Cursor-paged member list joined with the user record the UI renders. */
914	export async function listMembers(
915	  input: ListMembersInput,
916	): Promise<Page<MemberWithUser>> {
917	  const db = getDb();
918	  const sort = { sortColumn: members.createdAt, idColumn: members.id };
919	
920	  const filters = compact(
921	    orgPredicate(members.orgId, input.orgId),
922	    liveMemberPredicate(),
923	    input.role === undefined ? undefined : eq(members.role, input.role),
924	    input.status === undefined ? undefined : eq(members.status, input.status),
925	    input.query === undefined
926	      ? undefined
927	      : or(
928	          like(users.name, `%${input.query}%`),
929	          like(users.email, `%${input.query}%`),
930	        ),
931	  );
932	
933	  const total = db
934	    .select({ value: count() })
935	    .from(members)
936	    .innerJoin(users, eq(users.id, members.userId))
937	    .where(and(...filters))
938	    .get();
939	
940	  const rows = db
941	    .select({ member: members, user: users })
942	    .from(members)
943	    .innerJoin(users, eq(users.id, members.userId))
944	    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
945	    .orderBy(desc(members.createdAt), desc(members.id))
946	    .limit(probeLimit(input.limit))
947	    .all();
