949	  return toPage(
950	    rows,
951	    input.limit,
952	    total?.value ?? 0,
953	    (row) => ({ ...toMember(row.member), user: toUser(row.user) }),
954	    (row) => ({ id: row.member.id, sortValue: row.member.createdAt }),
955	  );
