1158	/** Slugs the router or marketing pages already claim. */
1159	export const RESERVED_SLUGS: readonly string[] = [
1160	  "admin",
1161	  "api",
1162	  "auth",
1163	  "billing",
1164	  "blog",
1165	  "changelog",
1166	  "dashboard",
1167	  "docs",
1168	  "help",
1169	  "login",
1170	  "logout",
1171	  "new",
1172	  "pricing",
