1181	/** Lowercases, strips diacritics and punctuation, collapses to `a-z0-9-`. */
1182	export function slugify(input: string): string {
1183	  return input
1184	    .normalize("NFKD")
1185	    .replace(/[\u0300-\u036f]/g, "")
1186	    .toLowerCase()
1187	    .replace(/[^a-z0-9]+/g, "-")
1188	    .replace(/^-+|-+$/g, "")
1189	    .slice(0, SLUG_MAX_LENGTH)
1190	    .replace(/-+$/g, "");
1191	}
1192	
1193	export function isValidSlug(value: string): boolean {
1194	  return (
1195	    value.length >= SLUG_MIN_LENGTH &&
1196	    value.length <= SLUG_MAX_LENGTH &&
1197	    SLUG_PATTERN.test(value)
1198	  );
1199	}
1200	
1201	export function isReservedSlug(value: string): boolean {
1202	  return RESERVED_SLUGS.includes(value);
1203	}
