1205	export class InvalidSlugError extends Error {
1206	  readonly code = "validation_failed" as const;
1207	
1208	  constructor(readonly value: string, readonly reason: string) {
1209	    super(`Invalid slug "${value}": ${reason}`);
1210	    this.name = "InvalidSlugError";
1211	  }
1212	}
1213	
1214	export function assertValidSlug(value: string): void {
1215	  if (!isValidSlug(value)) {
1216	    throw new InvalidSlugError(value, "must match ^[a-z0-9]+(-[a-z0-9]+)*$");
1217	  }
1218	  if (isReservedSlug(value)) {
1219	    throw new InvalidSlugError(value, "is reserved");
1220	  }
1221	}
