1223	/**
1224	 * Derives a slug from `input` that collides with nothing in `taken`, by
1225	 * appending `-2`, `-3`, … Repositories pass their existing slug set in.
1226	 */
1227	export function uniqueSlug(input: string, taken: Iterable<string>): string {
1228	  const base = slugify(input) || "item";
1229	  const used = new Set(taken);
1230	  if (!used.has(base) && !isReservedSlug(base)) return base;
1231	
1232	  for (let suffix = 2; suffix < 1_000; suffix += 1) {
1233	    const candidate = `${base.slice(0, SLUG_MAX_LENGTH - 5)}-${suffix}`;
1234	    if (!used.has(candidate) && !isReservedSlug(candidate)) return candidate;
1235	  }
1236	  throw new InvalidSlugError(base, "exhausted unique suffixes");
1237	}
