95	 * Permanently removes rows archived longer ago than the plan's `retentionDays`.
96	 *
97	 * Must call (do not reimplement): getPlanLimits, isArchived
98	 */
99	import { getPlanLimits } from "@/config/plan-limits";
100	import { createLogger } from "@/lib/logger";
101	import { isArchived } from "@/lib/soft-delete";
102	import * as activityRepo from "@/server/repositories/activity-repository";
103	import * as issueRepo from "@/server/repositories/issue-repository";
104	import * as orgRepo from "@/server/repositories/organization-repository";
105	import * as searchRepo from "@/server/repositories/search-repository";
106	import * as usageRepo from "@/server/repositories/usage-repository";
107	import { toIsoTimestamp } from "@/types/common";
108	import { runJob } from "./types";
109	import type { JobResult } from "@/server/jobs/types";
110	
111	const ORG_BATCH = 25;
112	const PAGE_SIZE = 100;
113	const MS_PER_DAY = 24 * 60 * 60 * 1000;
114	
115	const logger = createLogger("cleanup-archived-job");
116	
117	/**
118	 * The retention sweep. Soft-deleted rows are kept for as long as the plan
119	 * promises and no longer: the cut-off comes from `retentionDays`, so an
120	 * enterprise tenant keeps years of history where a free one keeps a month.
121	 *
122	 * Only the search documents are actually dropped here — the issue rows stay,
123	 * because the audit log still points at them — while the audit rows past the
124	 * window are purged outright.
125	 */
126	export async function runCleanupArchivedJob(now: Date): Promise<JobResult> {
127	  return runJob("cleanup-archived", async (result) => {
128	    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);
129	
130	    for (const orgId of orgIds) {
131	      const org = await orgRepo.findOrgById(orgId);
132	      if (!org) continue;
133	
134	      const { retentionDays } = getPlanLimits(org.plan);
135	      const cutoff = toIsoTimestamp(
136	        new Date(now.getTime() - retentionDays * MS_PER_DAY),
137	      );
138	
139	      const archived = await issueRepo.listIssues({
140	        orgId,
141	        limit: PAGE_SIZE,
142	        cursor: null,
143	        includeArchived: true,
144	      });
145	
146	      for (const issue of archived.items) {
147	        if (!isArchived(issue)) continue;
148	        if (issue.archivedAt === null || issue.archivedAt > cutoff) continue;
149	
150	        await searchRepo.deleteSearchDocument(orgId, "issue", issue.id);
151	        result.processed += 1;
152	      }
153	
154	      try {
155	        const purged = await activityRepo.purgeActivityBefore(orgId, cutoff);
156	        result.processed += purged;
157	      } catch (error) {
158	        result.failed += 1;
159	        logger.error("activity purge failed", {
160	          orgId,
161	          reason: error instanceof Error ? error.message : String(error),
162	        });
163	      }
164	    }
165	  });
166	}
167	/**
168	 * Builds and 'sends' the daily digest for every subscriber of every org whose digest hour has arrived.
169	 *
170	 * Must call (do not reimplement): isEnabled, buildDigest, sendEmail
171	 */
172	import { isEnabled } from "@/lib/feature-flags";
173	import { createLogger } from "@/lib/logger";
174	import * as notificationRepo from "@/server/repositories/notification-repository";
175	import * as orgRepo from "@/server/repositories/organization-repository";
176	import * as usageRepo from "@/server/repositories/usage-repository";
177	import * as userRepo from "@/server/repositories/user-repository";
178	import { buildDigest, listDigestRecipients, renderDigest } from "@/server/services/digest-service";
179	import { sendEmail } from "@/server/services/email-service";
180	import { buildFlagContext } from "@/server/services/feature-flag-service";
181	import { toIsoTimestamp } from "@/types/common";
182	import { runJob } from "./types";
183	import type { JobResult } from "@/server/jobs/types";
184	import type { Organization } from "@/types/organization";
185	
186	const ORG_BATCH = 50;
187	const MS_PER_DAY = 24 * 60 * 60 * 1000;
188	
189	const logger = createLogger("digest-email-job");
190	
191	/**
192	 * One pass per scheduler tick. Each org is only processed during the UTC hour
193	 * it configured, so a tick that runs every few minutes still sends exactly one
194	 * digest per day per recipient.
195	 */
196	export async function runDigestEmailJob(now: Date): Promise<JobResult> {
197	  return runJob("digest-email", async (result) => {
198	    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);
199	
200	    for (const orgId of orgIds) {
201	      const org = await orgRepo.findOrgById(orgId);
202	      if (!org || !shouldRunForOrg(org, now)) continue;
203	
204	      if (!isEnabled("digest_email", buildFlagContext(null, org))) continue;
205	
206	      const windowEnd = toIsoTimestamp(now);
207	      const windowStart = toIsoTimestamp(new Date(now.getTime() - MS_PER_DAY));
208	
209	      for (const recipientId of await listDigestRecipients(orgId)) {
210	        try {
211	          const bundle = await buildDigest(
212	            orgId,
213	            recipientId,
214	            windowStart,
215	            windowEnd,
216	          );
217	          if (!bundle) continue;
218	
219	          const recipient = await userRepo.findUserById(recipientId);
220	          if (!recipient) continue;
221	
222	          const rendered = await renderDigest(bundle, recipient);
223	          await sendEmail({ to: recipient.email, ...rendered });
224	
225	          // Once digested, these notifications are no longer "unread" — this
226	          // is what keeps a later run inside the same window from sending
227	          // the same digest twice.
228	          for (const entry of bundle.entries) {
229	            await notificationRepo.markRead(orgId, entry.notificationId, windowEnd);
230	          }
231	
232	          result.processed += 1;
233	        } catch (error) {
234	          result.failed += 1;
235	          logger.error("digest failed", {
236	            orgId,
237	            recipientId,
238	            reason: error instanceof Error ? error.message : String(error),
239	          });
240	        }
241	      }
242	    }
243	  });
244	}
