393	/** How many jobs `drain()` takes in one pass when no limit is given. */
394	const DEFAULT_DRAIN = 25;
395	
396	const logger = createLogger("job-queue");
397	
398	/**
399	 * The queue lives in module scope: Taskflow runs one server process and the
400	 * scheduler is started from `instrumentation.ts`, so there is no second
401	 * consumer to coordinate with. Swapping this for a real broker means
402	 * reimplementing these four functions and nothing else.
403	 */
404	const pending: QueuedJob[] = [];
