406	/** Idempotent on `id`: re-enqueuing a job keeps the earlier `runAt`. */
407	export function enqueue(job: QueuedJob): void {
408	  if (pending.some((queued) => queued.id === job.id)) return;
409	  pending.push(job);
410	}
411	
412	/**
413	 * Runs everything that is due, oldest first. A handler that throws is put back
414	 * with an exponential delay until `MAX_ATTEMPTS`, then dropped with a log line
415	 * — an infinitely retrying job is worse than a lost one.
416	 */
417	export async function drain(limit: number = DEFAULT_DRAIN): Promise<number> {
418	  const now = new Date().toISOString();
419	  const due = pending
420	    .filter((job) => job.runAt <= now)
421	    .sort((a, b) => (a.runAt < b.runAt ? -1 : 1))
422	    .slice(0, Math.max(0, limit));
423	
424	  let completed = 0;
425	
426	  for (const job of due) {
427	    remove(job.id);
428	
429	    try {
430	      await runHandler(job);
431	      completed += 1;
432	    } catch (error) {
433	      const attempts = job.attempts + 1;
434	
435	      if (attempts >= MAX_ATTEMPTS) {
436	        logger.error("job dropped after max attempts", {
437	          id: job.id,
438	          kind: job.kind,
439	          attempts,
440	        });
441	        continue;
442	      }
443	
444	      pending.push({
445	        ...job,
446	        attempts,
447	        runAt: toIsoTimestamp(new Date(Date.now() + backoffMs(attempts))),
448	      });
449	
450	      logger.warn("job retry scheduled", {
451	        id: job.id,
452	        kind: job.kind,
453	        attempts,
454	        reason: error instanceof Error ? error.message : String(error),
455	      });
456	    }
457	  }
458	
459	  return completed;
460	}
