471	/** 1s, 2s, 4s, 8s … capped at one minute. */
472	function backoffMs(attempts: number): number {
473	  return Math.min(60_000, 2 ** (attempts - 1) * 1_000);
474	}
475	
476	function remove(id: string): void {
477	  const at = pending.findIndex((job) => job.id === id);
478	  if (at >= 0) pending.splice(at, 1);
479	}
