537	/** How often `tick()` runs once the scheduler is started. */
538	const TICK_INTERVAL_MS = 60_000;
539	
540	/** Minimum gap between two runs of the same job kind, in minutes. */
541	const CADENCE_MINUTES: Readonly<Record<JobKind, number>> = {
542	  "digest-email": 60,
543	  "overdue-issues": 60,
544	  "webhook-delivery": 1,
545	  "usage-rollup": 15,
546	  "search-reindex": 1_440,
547	  "cleanup-archived": 1_440,
548	  "trial-expiry": 360,
549	};
550	
551	const logger = createLogger("job-scheduler");
552	
553	let timer: ReturnType<typeof setInterval> | null = null;
554	const lastRunAt = new Map<JobKind, number>();
555	
556	/**
557	 * Starts the interval. Idempotent, and `unref()`ed so a pending tick never
558	 * keeps a process alive — a scheduler that blocks shutdown is worse than one
559	 * that misses the last tick.
560	 */
561	export function startScheduler(): void {
562	  if (timer !== null) return;
563	
564	  timer = setInterval(() => {
565	    void tick(new Date()).catch((error: unknown) => {
566	      logger.error("scheduler tick failed", {
567	        reason: error instanceof Error ? error.message : String(error),
568	      });
569	    });
570	  }, TICK_INTERVAL_MS);
571	
572	  timer.unref?.();
573	  logger.info("scheduler started", { intervalMs: TICK_INTERVAL_MS });
574	}
575	
576	export function stopScheduler(): void {
577	  if (timer === null) return;
578	  clearInterval(timer);
579	  timer = null;
580	  lastRunAt.clear();
581	}
582	
583	export function isSchedulerRunning(): boolean {
584	  return timer !== null;
585	}
