587	/**
588	 * One pass: enqueue whatever cadence says is due, then drain the queue. Split
589	 * out from the interval so tests can drive it with an explicit clock instead
590	 * of waiting a minute.
591	 */
592	export async function tick(now: Date): Promise<void> {
593	  for (const kind of Object.keys(CADENCE_MINUTES) as JobKind[]) {
594	    if (!isDue(kind, now)) continue;
595	
596	    lastRunAt.set(kind, now.getTime());
597	    enqueue({
598	      id: `${kind}:${Math.floor(now.getTime() / 60_000)}`,
599	      kind,
600	      runAt: toIsoTimestamp(now),
601	      attempts: 0,
602	      payload: {},
603	    });
604	  }
605	
606	  const completed = await drain();
607	  if (completed > 0 || pendingCount() > 0) {
608	    logger.debug("tick complete", { completed, pending: pendingCount() });
609	  }
610	}
611	
612	function isDue(kind: JobKind, now: Date): boolean {
613	  const previous = lastRunAt.get(kind);
614	  if (previous === undefined) return true;
615	  return now.getTime() - previous >= CADENCE_MINUTES[kind] * 60_000;
616	}
