408	/**
409	 * Claims a batch for the delivery job. Cross-tenant on purpose — the queue is
410	 * drained by a background worker, not by a request — and the attempt counter
411	 * is bumped on claim so a crashed worker cannot retry forever.
412	 */
413	export async function claimPendingDeliveries(
414	  limit: number,
415	): Promise<readonly WebhookDeliveryRow[]> {
416	  const db = getDb();
417	  const pending = db
418	    .select()
419	    .from(webhookDeliveries)
420	    .where(eq(webhookDeliveries.status, "pending"))
421	    .orderBy(asc(webhookDeliveries.createdAt))
422	    .limit(Math.max(1, limit))
423	    .all();
