425	  return pending.map((row) =>
426	    db
427	      .update(webhookDeliveries)
428	      .set({
429	        attempts: row.attempts + 1,
430	        updatedAt: toIsoTimestamp(new Date()),
431	      })
432	      .where(eq(webhookDeliveries.id, row.id))
433	      .returning()
434	      .get(),
435	  );
