654	/**
655	 * Bulk invite. The seat quota is checked once for the whole batch — inviting
656	 * five people into a plan with three free seats must fail as a batch rather
657	 * than half-succeeding — and the rate limit is charged per invite.
658	 */
659	export async function inviteMembers(
660	  actor: Actor,
661	  input: InviteMembersInput,
662	): Promise<readonly Invitation[]> {
663	  assertOrgScope(actor, input.orgId);
664	  assertCan(actor, "member:invite", orgResource(input.orgId));
665	
666	  const verdict = await consumeRateLimit(
667	    input.orgId,
668	    INVITE_BUCKET,
669	    input.invites.length,
670	  );
671	  if (!verdict.allowed) {
672	    throw new Error(
673	      `Invite rate limit reached; try again after ${verdict.resetAt}`,
674	    );
675	  }
676	
677	  const org = requireFound(
678	    await orgRepo.findOrgById(input.orgId),
679	    "Organization",
680	    input.orgId,
681	  );
682	
683	  const seatsUsed =
684	    (await memberRepo.countActiveMembers(input.orgId)) +
685	    (await invitationRepo.countPendingInvitations(input.orgId));
686	
687	  if (
688	    wouldExceedLimit(org.plan, "seats", seatsUsed, input.invites.length)
689	  ) {
690	    const limits = getPlanLimits(org.plan);
691	    throw new Error(
692	      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
693	    );
694	  }
695	
696	  const invitations: Invitation[] = [];
697	
698	  for (const invite of input.invites) {
699	    const token = randomToken(32);
700	    const invitation = await invitationRepo.insertInvitation(
701	      input.orgId,
702	      {
703	        orgId: input.orgId,
704	        email: invite.email,
705	        role: invite.role,
706	        expiresInDays: DEFAULT_EXPIRY_DAYS,
707	      },
708	      actor.userId,
709	      hashToken(token),
710	    );
711	
712	    invitations.push(invitation);
713	
714	    await emit("member.invited", {
715	      orgId: input.orgId,
716	      actorId: actor.userId,
717	      occurredAt: invitation.createdAt,
718	      email: invite.email,
719	      role: invite.role,
720	    });
721	  }
722	
723	  return invitations;
724	}
