726	/**
727	 * Accepting runs unauthenticated: the token is the credential, so there is no
728	 * `Actor` to scope against and every check has to come off the stored row.
729	 */
730	export async function acceptInvitation(
731	  userId: UserId,
732	  input: AcceptInvitationTokenInput,
733	): Promise<Member> {
734	  const invitation = requireFound(
735	    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
736	    "Invitation",
737	    "token",
738	  );
739	
740	  if (invitation.revokedAt !== null) {
741	    throw new Error("That invitation has been revoked");
742	  }
743	  if (invitation.acceptedAt !== null) {
744	    throw new Error("That invitation has already been accepted");
745	  }
746	  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
747	    throw new Error("That invitation has expired");
748	  }
749	
750	  const existing = await memberRepo.findMember(invitation.orgId, userId);
751	  if (existing) return existing;
752	
753	  const member = await memberRepo.insertMember(
754	    invitation.orgId,
755	    userId,
756	    invitation.role,
757	    invitation.invitedBy,
758	  );
759	
760	  await invitationRepo.markInvitationAccepted(
761	    invitation.orgId,
762	    invitation.id,
763	    toIsoTimestamp(new Date()),
764	  );
765	
766	  await emit("member.joined", {
767	    ...envelope(invitation.orgId, userId),
768	    memberId: member.id,
769	    userId,
770	    role: member.role,
771	  });
772	
773	  return member;
774	}
