929	  error: ZodError,
930	): Readonly<Record<string, readonly string[]>> {
931	  const fields: Record<string, string[]> = {};
932	  for (const issue of error.issues as readonly ZodIssue[]) {
933	    const key = issue.path.length === 0 ? "_root" : issue.path.join(".");
934	    (fields[key] ??= []).push(issue.message);
935	  }
936	  return fields;
