939	export function toAppError(error: unknown): AppErrorShape {
940	  if (error instanceof ZodError) {
941	    return {
942	      code: "validation_failed",
943	      message: "Please correct the highlighted fields.",
944	      fieldErrors: fieldErrorsFromZod(error),
945	    };
946	  }
947	
948	  if (error instanceof PermissionDeniedError) {
949	    return {
950	      code: "forbidden",
951	      message: error.message,
952	      meta: {
953	        action: error.action,
954	        resourceKind: error.decision.resourceKind,
955	        reason: error.decision.reason,
956	      },
957	    };
958	  }
959	
960	  if (error instanceof TenantScopeError) {
961	    return {
962	      code: "tenant_scope_violation",
963	      message: "That resource belongs to a different organization.",
964	      meta: { expectedOrgId: error.expectedOrgId, actualOrgId: error.actualOrgId },
965	    };
966	  }
967	
968	  if (error instanceof FeatureDisabledError) {
969	    return {
970	      code: "forbidden",
971	      message: error.message,
972	      meta: { flag: error.flag },
973	    };
974	  }
975	
976	  if (error instanceof AlreadyArchivedError) {
977	    return {
978	      code: "conflict",
979	      message: error.message,
980	      meta: { entity: error.entity, id: error.id },
981	    };
982	  }
983	
984	  if (error instanceof InvalidSlugError) {
985	    return {
986	      code: "validation_failed",
987	      message: error.message,
988	      fieldErrors: { slug: [error.message] },
989	      meta: { value: error.value },
990	    };
991	  }
992	
993	  return {
994	    code: "internal_error",
995	    message:
996	      error instanceof Error ? error.message : "Something went wrong. Try again.",
997	  };
998	}
