1016	/**
1017	 * In-process, typed publish/subscribe bus.
1018	 *
1019	 * Taskflow keeps `IssueService`, `NotificationService`, `ActivityService`, the
1020	 * search indexer and the webhook dispatcher decoupled: writers `emit()`, and
1021	 * every reactive concern `subscribe()`s at module init (see
1022	 * `src/server/services/event-registry.ts`). Handlers are isolated — one
1023	 * throwing handler never fails the emit or the sibling handlers.
1024	 */
1025	
1026	type HandlerSet = Set<EventHandler<TaskflowEventType>>;
1027	
1028	const handlers = new Map<TaskflowEventType, HandlerSet>();
1029	
1030	const errorSinks = new Set<(type: TaskflowEventType, error: unknown) => void>();
1031	
1032	/** Registers a handler for one event type. Call the return value to detach. */
1033	export function subscribe<K extends TaskflowEventType>(
1034	  type: K,
1035	  handler: EventHandler<K>,
1036	): Unsubscribe {
1037	  const set = handlers.get(type) ?? new Set();
1038	  set.add(handler as EventHandler<TaskflowEventType>);
1039	  handlers.set(type, set);
1040	  return () => {
1041	    set.delete(handler as EventHandler<TaskflowEventType>);
1042	  };
1043	}
