1045	/** Registers a handler that detaches itself after the first delivery. */
1046	export function subscribeOnce<K extends TaskflowEventType>(
1047	  type: K,
1048	  handler: EventHandler<K>,
1049	): Unsubscribe {
1050	  const off = subscribe(type, (payload) => {
1051	    off();
1052	    return handler(payload);
1053	  });
1054	  return off;
1055	}
