687	export async function buildDigest(
688	  orgId: OrgId,
689	  recipientId: UserId,
690	  windowStart: IsoTimestamp,
691	  windowEnd: IsoTimestamp,
692	): Promise<DigestBundle | null> {
693	  const org = await orgRepo.findOrgById(orgId);
