633	import type { Actor, Invitation, Member } from "@/types/member";
634	
635	/** Token bucket protecting the invite mailer from being used as a spam relay. */
636	const INVITE_BUCKET = "member:invite";
637	
638	/** Default validity of a freshly minted invitation, in days. */
639	const DEFAULT_EXPIRY_DAYS = 14;
640	
641	export async function inviteMember(
642	  actor: Actor,
643	  input: InviteMemberInput,
644	): Promise<Invitation> {
645	  const [invitation] = await inviteMembers(actor, {
646	    orgId: input.orgId,
647	    invites: [{ email: input.email, role: input.role }],
648	  });
649	
650	  if (!invitation) throw new Error("Invitation was not created");
