811	/**
812	 * Wires every subscriber at process start. Called once from `src/instrumentation.ts`; the only module that knows the full listener set.
813	 *
814	 * Must call (do not reimplement): subscribe, registerActivityListeners, registerSearchListeners, registerUsageListeners, registerWebhookListeners
815	 */
816	import { subscribe } from "@/lib/event-bus";
817	import { createLogger } from "@/lib/logger";
818	import { enqueue } from "@/server/jobs/queue";
819	import { toIsoTimestamp } from "@/types/common";
820	import { registerActivityListeners } from "./activity-service";
821	import { registerSearchListeners } from "./search-service";
822	import { registerUsageListeners } from "./usage-service";
823	import { registerWebhookListeners } from "./webhook-service";
824	import type { Unsubscribe } from "@/types/event";
