826	/**
827	 * Importing this module also loads `notification-service` transitively, which
828	 * attaches the notification fan-out on first import — that hub has no
829	 * `register*` entry point of its own.
830	 */
831	import "./notification-service";
832	
833	const logger = createLogger("event-registry");
834	
835	/** Non-null between `registerEventHandlers()` and `unregisterEventHandlers()`. */
836	let detach: Unsubscribe | null = null;
837	
838	/**
839	 * Attaches every subscriber exactly once. Idempotent: `instrumentation.ts`
840	 * runs per server process, but a hot reload in dev can call it again and must
841	 * not double-deliver every event.
842	 */
843	export function registerEventHandlers(): void {
844	  if (detach !== null) return;
845	
846	  const offs: Unsubscribe[] = [
847	    registerActivityListeners(),
848	    registerSearchListeners(),
849	    registerUsageListeners(),
850	    registerWebhookListeners(),
851	    registerDigestBridge(),
852	  ];
853	
854	  detach = () => {
855	    for (const off of offs) off();
856	  };
857	
858	  logger.info("event handlers registered", { groups: offs.length });
859	}
