1057	/**
1058	 * Publishes an event to every subscriber. Resolves once all handlers settle;
1059	 * rejected handlers are reported to the error sinks, never rethrown.
1060	 */
1061	export async function emit<K extends TaskflowEventType>(
1062	  type: K,
1063	  payload: TaskflowEventPayload<K>,
1064	): Promise<void> {
1065	  const set = handlers.get(type);
1066	  if (!set || set.size === 0) return;
1067	
1068	  const results = await Promise.allSettled(
1069	    [...set].map(async (handler) => {
1070	      await (handler as EventHandler<K>)(payload);
1071	    }),
1072	  );
1073	
1074	  for (const result of results) {
1075	    if (result.status === "rejected") {
1076	      reportHandlerError(type, result.reason);
1077	    }
1078	  }
1079	}
1080	
1081	/** Fire-and-forget variant for call sites that must not await delivery. */
1082	export function emitAndForget<K extends TaskflowEventType>(
1083	  type: K,
1084	  payload: TaskflowEventPayload<K>,
1085	): void {
1086	  void emit(type, payload).catch((error: unknown) => {
1087	    reportHandlerError(type, error);
1088	  });
1089	}
1090	
1091	export function onHandlerError(
1092	  sink: (type: TaskflowEventType, error: unknown) => void,
1093	): Unsubscribe {
1094	  errorSinks.add(sink);
1095	  return () => {
1096	    errorSinks.delete(sink);
1097	  };
1098	}
1099	
1100	function reportHandlerError(type: TaskflowEventType, error: unknown): void {
1101	  for (const sink of errorSinks) {
1102	    try {
1103	      sink(type, error);
1104	    } catch {
1105	      // A failing error sink must never escalate.
1106	    }
1107	  }
1108	}
