import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import { getDb, webhookDeliveries } from "@/server/db";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerEventHandlers(); });
afterAll(() => cleanup());

it("closing is final", async () => {
  const a = await createTenant("closing", "growth");
  const b = await createTenant("other", "growth");
  // shared member
  await memberRepo.insertMember(b.org.id, a.userIds.member, "member", null);
  await usageRepo.recomputeUsage(a.org.id);
  await usageRepo.recomputeUsage(b.org.id);

  const issue = await issueService.createIssue(a.actors.owner, issueInput(a.org.id, a.project.id, { assigneeId: a.userIds.member, dueAt: "2026-01-01T00:00:00.000Z" }));
  const token = "t".repeat(43);
  await invitationRepo.insertInvitation(a.org.id, { orgId: a.org.id, email: "x@y.test", role: "member", expiresInDays: 14 }, a.userIds.owner, hashToken(token));
  const ep = await webhookRepo.insertEndpoint({ orgId: a.org.id, url: "https://e.test/h", eventTypes: ["issue.created", "billing.plan_changed"] } as never, "s");
  await webhookRepo.enqueueDelivery(a.org.id, ep.id, "issue.created", "{}");
  const sub0 = await subscriptionRepo.findSubscription(a.org.id);
  expect(sub0?.status).toBe("trialing");

  await expect(orgService.deleteOrganization(a.actors.owner, { orgId: a.org.id, confirmSlug: "nope" })).rejects.toThrow(/confirmation/);
  expect((await orgService.listOrganizationsForUser(a.userIds.member)).length).toBe(2);

  await orgService.deleteOrganization(a.actors.owner, { orgId: a.org.id, confirmSlug: a.org.slug });
  const err = await orgService.deleteOrganization(a.actors.owner, { orgId: a.org.id, confirmSlug: a.org.slug }).catch((e) => e);
  expect(toAppError(err).code).toBe("conflict");

  expect((await orgService.listOrganizationsForUser(a.userIds.member)).map((o) => o.id)).toEqual([b.org.id]);
  expect(await orgService.resolveOrgBySlug(a.org.slug)).toBeNull();
  const principal = { userId: a.userIds.member, email: "e", activeOrgId: a.org.id, expiresAt: "2099-01-01T00:00:00.000Z" } as never;
  expect(await sessionService.resolveActorForOrg(principal, a.org.slug)).toBeNull();
  expect(await sessionService.resolveActorForOrg(principal, b.org.slug)).not.toBeNull();
  await expect(sessionService.switchActiveOrg(principal, { orgId: a.org.id })).rejects.toThrow();
  await expect(issueService.listIssues(a.actors.member, { orgId: a.org.id, limit: 10, cursor: null } as never)).rejects.toThrow();
  await expect(projectService.listProjects(a.actors.member, { orgId: a.org.id, limit: 10, cursor: null } as never)).rejects.toThrow();
  await expect(orgService.getOrganizationSummary(a.actors.owner, a.org.id)).rejects.toThrow();
  await projectService.listProjects(b.actors.member, { orgId: b.org.id, limit: 10, cursor: null } as never);

  const invitee = await userRepo.insertUser({ email: "x@y.test", name: "x", passwordHash: "s" });
  const joined: unknown[] = [];
  subscribe("member.joined", (p) => { joined.push(p); });
  const changed: unknown[] = [];
  subscribe("billing.plan_changed", (p) => { changed.push(p); });
  await expect(invitationService.acceptInvitation(invitee.id, { token } as never)).rejects.toThrow();
  expect(joined.length).toBe(0);
  expect(await memberRepo.findMember(a.org.id, invitee.id)).toBeNull();

  const later = new Date(Date.now() + 30 * 86400000);
  const o = await runOverdueIssueJob(later);
  expect(o.processed).toBe(0);
  const w = await runWebhookDeliveryJob(later);
  expect(w.processed).toBe(0);
  const rows = getDb().select().from(webhookDeliveries).all();
  expect(rows.filter((r) => r.orgId === a.org.id).every((r) => r.status === "failed")).toBe(true);
  const t = await runTrialExpiryJob(later);
  expect(changed.filter((c) => (c as { orgId: string }).orgId === a.org.id).length).toBe(0);
  expect(changed.length).toBe(1); // other tenant still expires
  expect((await subscriptionRepo.findSubscription(a.org.id))?.status).toBe("canceled");
  expect((await runSearchReindexJob(a.org.id)).processed).toBe(0);
  expect((await runSearchReindexJob(b.org.id)).processed).toBeGreaterThan(0);
  const acts = await activityRepo.listActivity({ orgId: a.org.id, limit: 50, cursor: null } as never);
  expect(acts.items.filter((x) => x.action === "billing.plan_changed").length).toBe(0);
  void issue; void t; void notificationRepo;

  const again = await orgService.createOrganization(a.userIds.owner, { name: "again", slug: a.org.slug, plan: "free" });
  expect(again.slug).not.toBe(a.org.slug);
});
